export function ClientState({
  stateKey = "{{stateKey}}",
  value = "{{value}}",
  accent = "{{accent}}",
  showNote = {{showNote}},
}) {
  return (
    <div style={{ font: "13px/1.5 system-ui, sans-serif", color: "#241430", background: "#FAF7F2", padding: 18, borderRadius: 12, width: 300, boxSizing: "border-box" }}>
      <div style={{ border: `2px solid ${accent}`, borderRadius: 10, padding: 12 }}>
        <p style={{ margin: "0 0 8px", fontSize: 10, color: "#24143099", textTransform: "uppercase", letterSpacing: ".04em" }}>Browser tab</p>
        <code style={{ display: "block", fontFamily: "ui-monospace, monospace", fontSize: 12, background: "#24143012", padding: "8px 10px", borderRadius: 6 }}>{stateKey} = {value}</code>
      </div>
      {showNote && <p style={{ margin: "10px 0 0", fontSize: 10, color: "#24143099" }}>Lives only in this tab's memory &mdash; refresh the page and it resets; the server never sees it.</p>}
    </div>
  );
}
